    pub revision: u64,
    pub violations: Option<[u64; 4]>,
    pub certificate: Certificate,
}

// The solver's grouping code is deliberately not used here.  A service task is
// already bound to a routing template, and a cache-group reservation is the
// union of the footprints of the tasks in that service group.  Keeping the
// union as reference counts makes a proposal cheap even when a large group is
// edited repeatedly.
pub struct Ledger {
    num_nodes: usize,
    task_count: usize,
    group_count: usize,
    footprints: Vec<Vec<usize>>,
    domains: Vec<usize>,

    tasks: Vec<Task>,
    quotas: Vec<u64>,
    budgets: Vec<u64>,
    capacities: Vec<u64>,

    members: Vec<u32>,
    loads: Vec<u64>,
    // Number of tasks in each group's footprint at each node.
    fp_counts: Vec<u32>,
    usage: Vec<i64>,

    // Pair counts are kept per group because a group can have many distinct
    // pairs while a transaction is being tested.  A legal committed group has
    // at most one pair.
    pair_counts: Vec<HashMap<(usize, u64), u32>>,
    unique_pairs: Vec<usize>,
    single_pair: Vec<Option<(usize, u64)>>,

    protected_by_group: Vec<u64>,
    revision: u64,

    // Per-transaction scratch.  A stamp avoids clearing arrays proportional to
    // the number of tasks for a small edit transaction.
    stamp: u64,
    task_stamp: Vec<u64>,
    task_original: Vec<Task>,
    touched_tasks: Vec<usize>,
    group_stamp: Vec<u64>,
    original_quota: Vec<u64>,
    original_budget: Vec<u64>,
    touched_groups: Vec<usize>,
    node_stamp: Vec<u64>,
    original_capacity: Vec<u64>,
    touched_nodes: Vec<usize>,
}

impl Ledger {
    pub fn new(
        problem: &SolverProblem,
        tasks: Vec<Task>,
        quotas: Vec<u64>,
        budgets: Vec<u64>,
        capacities: Vec<u64>,
    ) -> Result<Self, String> {
        let num_nodes = problem.num_nodes;
        let task_count = tasks.len();
        let group_count = quotas.len();
        if capacities.len() != num_nodes || budgets.len() != group_count {
            return Err("configuration length".into());
        }

        // Translate a template to the domain used by the protocol.  For all
        // ordinary topologies this is the source merge-group number.  The
        // dragonfly target scope is represented by demand_merge_classes, which
        // is exactly the source-node/destination-group domain.
        let mut source_domain = vec![usize::MAX; num_nodes];
        for (domain, nodes) in problem.source_merge_groups.iter().enumerate() {
            for &node in nodes {
                if node >= num_nodes || source_domain[node] != usize::MAX {
                    return Err("bad source domains".into());
                }
                source_domain[node] = domain;
            }
        }
        let mut domains = Vec::with_capacity(problem.demands.len());
        for (id, demand) in problem.demands.iter().enumerate() {
            let domain = if let Some(classes) = &problem.demand_merge_classes {
                if id >= classes.len() { return Err("bad demand classes".into()); }
                classes[id]
            } else {
                if demand.src >= source_domain.len() || source_domain[demand.src] == usize::MAX {
                    return Err("unmapped demand source".into());
                }
                source_domain[demand.src]
            };
            domains.push(domain);
        }
        let footprints: Vec<Vec<usize>> = problem
            .demands
            .iter()
            .map(|d| {
                let mut x = d.footprint.clone();
                x.sort_unstable();
                x.dedup();
                x
            })
            .collect();

        for task in &tasks {
            if task.template >= footprints.len()
                || task.group >= group_count
                || task.weight == 0
            {
                return Err("task out of range".into());
            }
        }

        let mut ledger = Self {
            num_nodes,
            task_count,
            group_count,
            footprints,
            domains,
            tasks,
            quotas,
            budgets,
            capacities,
            members: vec![0; group_count],
            loads: vec![0; group_count],
            fp_counts: vec![0; group_count * num_nodes],
            usage: vec![0; num_nodes],
            pair_counts: (0..group_count).map(|_| HashMap::new()).collect(),
            unique_pairs: vec![0; group_count],
            single_pair: vec![None; group_count],
            protected_by_group: vec![0; group_count],
            revision: 0,
            stamp: 0,
            task_stamp: vec![0; task_count],
            task_original: vec![Task { template: 0, group: 0, weight: 0, class: 0, pinned: false }; task_count],
            touched_tasks: Vec::new(),
            group_stamp: vec![0; group_count],
            original_quota: vec![0; group_count],
            original_budget: vec![0; group_count],
            touched_groups: Vec::new(),
            node_stamp: vec![0; num_nodes],
            original_capacity: vec![0; num_nodes],
            touched_nodes: Vec::new(),
        };

        // Construct all reservations from scratch.  This also gives the
        // precise initial legality check, rather than relying on a heuristic
        // solver result.
        for id in 0..ledger.task_count {
            let task = ledger.tasks[id];
            ledger.add_contribution(task);
            if task.pinned {
                ledger.protected_by_group[task.group] += 1;
            }
        }
        if ledger.violation_counts().0 != 0
            || ledger.violation_counts().1 != 0
            || ledger.violation_counts().2 != 0
        {
            return Err("illegal initial configuration".into());
        }
        Ok(ledger)
    }

    pub fn certificate(&self, query: &Query) -> Certificate {
        let mut totals = [0u64; 4];
        totals[1] = self.usage.iter().map(|&x| x.max(0) as u64).sum();
        totals[2] = self.tasks.iter().map(|t| t.weight).sum();
        totals[3] = self.tasks.iter().filter(|t| t.pinned).count() as u64;
        totals[0] = self.members.iter().filter(|&&x| x != 0).count() as u64;

        let mut groups = Vec::with_capacity(query.groups.len());
        for &id in &query.groups {
            let count = self.members[id];
            let (domain, class) = if count == 0 {
                (-1, -1)
            } else if let Some((d, c)) = self.single_pair[id] {
                (d as i64, c as i64)
            } else {
                // This branch is only needed while defensive code is used on
                // an illegal state; committed states have one pair.
                let p = self.pair_counts[id].keys().next().copied().unwrap_or((0, 0));
                (p.0 as i64, p.1 as i64)
            };
            let fp = self.footprint_size(id);
            groups.push([
                id as i64,
                count as i64,
                self.loads[id] as i64,
                self.quotas[id] as i64,
                self.budgets[id] as i64,
                fp as i64,
                domain,
                class,
            ]);
        }

        let mut nodes = Vec::with_capacity(query.nodes.len());
        for &id in &query.nodes {
            nodes.push([id as u64, self.usage[id].max(0) as u64, self.capacities[id]]);
        }

        let mut task_rows = Vec::with_capacity(query.tasks.len());
        for &id in &query.tasks {
            let t = self.tasks[id];
            task_rows.push([
                id as u64,
                t.group as u64,
                t.template as u64,
                t.weight,
                t.class,
                t.pinned as u64,
            ]);
        }
        Certificate { totals, groups, nodes, tasks: task_rows }
    }

    pub fn transact(&mut self, expected: u64, edits: &[Edit], query: &Query) -> Outcome {
        if expected != self.revision {
            return Outcome {
                accepted: false,
                revision: self.revision,
                violations: None,
                certificate: self.certificate(query),
            };
        }

        self.begin_transaction();
        for edit in edits {
            self.apply_edit(edit);
        }

        let (capacity, mixed, work, _) = self.violation_counts();
        let pins = self.pin_violations();
        let violations = [capacity, mixed, work, pins];
        let accepted = violations == [0, 0, 0, 0];

        if accepted {
            for &id in &self.touched_tasks {
                let old = self.task_original[id];
                let new = self.tasks[id];
                if old.pinned { self.protected_by_group[old.group] -= 1; }
                if new.pinned { self.protected_by_group[new.group] += 1; }
            }
            self.revision += 1;
        } else {
            self.rollback();
        }

        let revision = self.revision;
        let certificate = self.certificate(query);
        Outcome { accepted, revision, violations: Some(violations), certificate }
    }

    fn begin_transaction(&mut self) {
        self.stamp = self.stamp.wrapping_add(1);
        if self.stamp == 0 {
            self.task_stamp.fill(0);
            self.group_stamp.fill(0);
            self.node_stamp.fill(0);
            self.stamp = 1;
        }
        self.touched_tasks.clear();
        self.touched_groups.clear();
        self.touched_nodes.clear();
    }

    fn touch_task(&mut self, id: usize) {
        if self.task_stamp[id] != self.stamp {
            self.task_stamp[id] = self.stamp;
            self.task_original[id] = self.tasks[id];
            self.touched_tasks.push(id);
        }
    }

    fn touch_group(&mut self, id: usize) {
        if self.group_stamp[id] != self.stamp {
            self.group_stamp[id] = self.stamp;
            self.original_quota[id] = self.quotas[id];
            self.original_budget[id] = self.budgets[id];
            self.touched_groups.push(id);
        }
    }

    fn touch_node(&mut self, id: usize) {
        if self.node_stamp[id] != self.stamp {
            self.node_stamp[id] = self.stamp;
            self.original_capacity[id] = self.capacities[id];
            self.touched_nodes.push(id);
        }
    }

    fn apply_edit(&mut self, edit: &Edit) {
        match *edit {
            Edit::Move(id, group) => {
                self.touch_task(id);
                let mut t = self.tasks[id];
                if t.group != group {
                    self.remove_contribution(t);
                    t.group = group;
                    self.tasks[id] = t;
                    self.add_contribution(t);
                }
            }
            Edit::Weight(id, weight) => {
                self.touch_task(id);
                let mut t = self.tasks[id];
                if t.weight != weight {
                    self.remove_contribution(t);
                    t.weight = weight;
                    self.tasks[id] = t;
                    self.add_contribution(t);
                }
            }
            Edit::Class(id, class) => {
                self.touch_task(id);
                let mut t = self.tasks[id];
                if t.class != class {
                    self.remove_contribution(t);
                    t.class = class;
                    self.tasks[id] = t;
                    self.add_contribution(t);
                }
            }
            Edit::Bind(id, template) => {
                self.touch_task(id);
                let mut t = self.tasks[id];
                if t.template != template {
                    self.remove_contribution(t);
                    t.template = template;
                    self.tasks[id] = t;
                    self.add_contribution(t);
                }
            }
            Edit::Pin(id, pinned) => {
                self.touch_task(id);
                self.tasks[id].pinned = pinned;
            }
            Edit::Quota(id, quota) => {
                self.touch_group(id);
                self.change_quota(id, quota);
            }
            Edit::Budget(id, budget) => {
                self.touch_group(id);
                self.budgets[id] = budget;
            }
            Edit::Cap(id, capacity) => {
                self.touch_node(id);
                self.capacities[id] = capacity;
            }
        }
    }

    fn rollback(&mut self) {
        // Restore task contributions under the proposal's quotas first.  The
        // subsequent quota restoration then changes the reservation for the
        // now-restored footprint, so the order is important.
        let touched = self.touched_tasks.clone();
        for id in touched {
            let current = self.tasks[id];
            let old = self.task_original[id];
            if current.template != old.template
                || current.group != old.group
                || current.weight != old.weight
                || current.class != old.class
            {
                self.remove_contribution(current);
                self.tasks[id] = old;
                self.add_contribution(old);
            } else {
                self.tasks[id] = old;
            }
        }
        let groups = self.touched_groups.clone();
        for id in groups {
            let old_quota = self.original_quota[id];
            self.change_quota(id, old_quota);
            self.budgets[id] = self.original_budget[id];
        }
        let nodes = self.touched_nodes.clone();
        for id in nodes {
            self.capacities[id] = self.original_capacity[id];
        }
    }

    fn add_contribution(&mut self, task: Task) {
        let g = task.group;
        self.members[g] += 1;
        self.loads[g] += task.weight;
        let pair = (self.domains[task.template], task.class);
        let map = &mut self.pair_counts[g];
        let old = map.get(&pair).copied().unwrap_or(0);
        map.insert(pair, old + 1);
        if old == 0 {
            self.unique_pairs[g] += 1;
            if self.unique_pairs[g] == 1 {
                self.single_pair[g] = Some(pair);
            } else {
                self.single_pair[g] = None;
            }
        }
        let base = g * self.num_nodes;
        for &node in &self.footprints[task.template] {
            let slot = base + node;
            if self.fp_counts[slot] == 0 {
                self.usage[node] += self.quotas[g] as i64;
            }
            self.fp_counts[slot] += 1;
        }
    }

    fn remove_contribution(&mut self, task: Task) {
        let g = task.group;
        let base = g * self.num_nodes;
        for &node in &self.footprints[task.template] {
            let slot = base + node;
            debug_assert!(self.fp_counts[slot] != 0);
            self.fp_counts[slot] -= 1;
            if self.fp_counts[slot] == 0 {
                self.usage[node] -= self.quotas[g] as i64;
            }
        }
        self.members[g] -= 1;
        self.loads[g] -= task.weight;
        let pair = (self.domains[task.template], task.class);
        let map = &mut self.pair_counts[g];
        let count = map.get(&pair).copied().unwrap_or(0);
        if count <= 1 {
            map.remove(&pair);
            self.unique_pairs[g] -= 1;
            if self.unique_pairs[g] == 1 {
                self.single_pair[g] = map.keys().next().copied();
            } else if self.unique_pairs[g] == 0 {
                self.single_pair[g] = None;
            } else {
                self.single_pair[g] = None;
            }
        } else {
            map.insert(pair, count - 1);
        }
    }

    fn change_quota(&mut self, group: usize, quota: u64) {
        let old = self.quotas[group];
        if old == quota { return; }
        let delta = quota as i64 - old as i64;
        let base = group * self.num_nodes;
        for node in 0..self.num_nodes {
            if self.fp_counts[base + node] != 0 {
                self.usage[node] += delta;
            }
        }
        self.quotas[group] = quota;
    }

    fn footprint_size(&self, group: usize) -> usize {
        let base = group * self.num_nodes;
        (0..self.num_nodes).filter(|&n| self.fp_counts[base + n] != 0).count()
    }

    // The fourth element is intentionally not used here; pins depend on the
    // beginning-of-transaction state and are calculated separately.
    fn violation_counts(&self) -> (u64, u64, u64, u64) {
        let capacity = self.usage.iter().zip(&self.capacities)
            .filter(|&(u, c)| *u > *c as i64).count() as u64;
        let mixed = self.unique_pairs.iter().filter(|&&x| x > 1).count() as u64;
        let mut work = 0u64;
        for g in 0..self.group_count {
            if self.members[g] != 0
                && (self.quotas[g] == 0
                    || (self.loads[g] as u128) > (self.quotas[g] as u128) * (self.budgets[g] as u128))
            {
                work += 1;
            }
        }
        (capacity, mixed, work, 0)
    }

    fn pin_violations(&self) -> u64 {
        let mut result = 0u64;
        let mut touched_pinned_by_group = vec![0u64; self.group_count];
        for &id in &self.touched_tasks {
            let old = self.task_original[id];
            if !old.pinned { continue; }
            touched_pinned_by_group[old.group] += 1;
            let quota_changed = self.quotas[old.group] != self.begin_quota(old.group);
            let now = self.tasks[id];
            if now.group != old.group
                || now.template != old.template
                || now.weight != old.weight
                || now.class != old.class
                || quota_changed
            {
                result += 1;
            }
        }
        // Untouched protected tasks can only be affected by a change to the
        // quota of their original group.
        for g in 0..self.group_count {
            if self.quotas[g] != self.begin_quota(g) {
                result += self.protected_by_group[g] - touched_pinned_by_group[g];
            }
        }
        result
    }

    fn begin_quota(&self, group: usize) -> u64 {
        if self.group_stamp[group] == self.stamp {
            self.original_quota[group]
        } else {
            self.quotas[group]
        }
    }
}
